actions.script:
                // NOTE: storeInfo prepared in always-actions above
                // set productStoreId in the session
                ec.web.sessionAttributes.productStoreId = productStoreId
                // add apiKey and moquiSessionToken for current user and session
                if (ec.user.username) { try { storeInfo.apiKey = ec.user.getLoginKey() } catch (Exception e) { } }
                else storeInfo.apiKey = null
                storeInfo.moquiSessionToken = ec.web.sessionToken
                String partyId = (ec.user.username ? ec.user.userAccount?.partyId : null) ?: ec.web.sessionAttributes.customerPartyId
                if (partyId) { storeInfo.customerInfo = ec.service.sync().name("popstore.CustomerServices.get#CustomerInfo").call() }
                // generate and send the JS response
                String storeInfoJson = groovy.json.JsonOutput.toJson(storeInfo)
                String jsText = """
var storeInfo = ${storeInfoJson};
\$.extend(storeConfig, storeInfo.productStore, storeInfo.settings);
"""
                ec.web.sendTextResponse(jsText, "application/javascript", null)

pre-actions.script:
import groovy.json.JsonSlurper
// get settings
JsonSlurper slurper = new JsonSlurper()
context.putAll(slurper.parseText(style))
// Lumina design tokens for the 'modern' template set: defaults below,
// overridable per store via a "lumina" object of hex colors in websiteColor.json.
// Emitted as "R G B" channel strings so Tailwind opacity modifiers work.
Map luminaDefaults = [
    surface: '#0b1326', surfaceContainerLowest: '#060e20', surfaceContainerLow: '#131b2e',
    surfaceContainer: '#171f33', surfaceContainerHigh: '#222a3d', surfaceContainerHighest: '#2d3449',
    onSurface: '#dae2fd', onSurfaceVariant: '#bccac0', primary: '#68dba9', onPrimary: '#003825',
    primaryContainer: '#25a475', secondary: '#4edea3', tertiary: '#45dfa4', error: '#ffb4ab',
    outline: '#87948b', outlineVariant: '#3d4a42']
Map luminaOverrides = context.lumina instanceof Map ? (Map) context.lumina : [:]
Map luminaChannels = [:]
Closure toChannels = { String value, String fallbackHex ->
    try {
        if (value ==~ /\d+ \d+ \d+/) return value
        String hex = value.startsWith('#') ? value.substring(1) : value
        return "${Integer.parseInt(hex.substring(0,2),16)} ${Integer.parseInt(hex.substring(2,4),16)} ${Integer.parseInt(hex.substring(4,6),16)}".toString()
    } catch (Exception e) {
        String hex = fallbackHex.substring(1)
        return "${Integer.parseInt(hex.substring(0,2),16)} ${Integer.parseInt(hex.substring(2,4),16)} ${Integer.parseInt(hex.substring(4,6),16)}".toString()
    }
}
luminaDefaults.each { String key, String defaultHex ->
    luminaChannels[key] = toChannels((luminaOverrides[key] ?: defaultHex).toString().trim(), defaultHex)
}
// brightness-aware chrome: contrast channel (white on dark, black on light) and
// the surface hex used for the theme-color meta tag / anti-FOUC style
String luminaBrightness = (context.luminaBrightness ?: 'dark').toString()
luminaChannels.contrast = (luminaBrightness == 'light') ? '0 0 0' : '255 255 255'
// the legacy header/footer are painted with primaryContainer, so they need its
// on-colour. Themes stored before onPrimaryContainer existed do not carry it:
// fall back to black or white picked from primaryContainer's own relative
// luminance (WCAG crossover is around 0.18), which is readable for any brand.
if (luminaOverrides.onPrimaryContainer) {
    luminaChannels.onPrimaryContainer =
        toChannels(luminaOverrides.onPrimaryContainer.toString().trim(), '#000000')
} else {
    // comparisons are written with > on purpose: a raw less-than character
    // anywhere in this script block would not be well-formed XML
    List pcLin = luminaChannels.primaryContainer.split(' ').collect{
        double c = (it as Integer) / 255.0d
        c > 0.03928d ? Math.pow((c + 0.055d) / 1.055d, 2.4d) : c / 12.92d }
    double pcLum = 0.2126d * pcLin[0] + 0.7152d * pcLin[1] + 0.0722d * pcLin[2]
    luminaChannels.onPrimaryContainer = (pcLum > 0.18d) ? '0 0 0' : '255 255 255'
}
context.luminaBrightness = luminaBrightness
context.luminaSurfaceHex = '#' + luminaChannels.surface.split(' ').collect{ String.format('%02x', it as Integer) }.join('')
context.lumina = luminaChannels
// get target filepath
newRef = ec.resource.getLocationReference("component://PopRestStore/screen/store/components/styles/${storeInfo.productStore.productStoreId}.css")
String newFilePath = newRef.getUrl().toExternalForm().substring(5)
// render ftl file
String location = "component://PopRestStore/screen/store/components/styles.css.ftl"
css = ec.resource.getTemplateRendererByLocation(location)
Writer fw = new FileWriter(newFilePath)
css.render(location, fw)
fw.close()

String seoPathInfo = ec.web.getPathInfo() ?: ''
// the locale mount is part of the url but not of the /content/ path below it
String seoLocalePath = seoPathInfo
if (urlPrefix) seoLocalePath = seoPathInfo.substring(urlPrefix.length())
if (wikiSpaceId && seoLocalePath.startsWith('/content/')) {
    String seoPagePath = seoLocalePath.substring('/content/'.length())
    if (seoPagePath) try {
        // an untranslated page falls back to the source language, like content.xml
        Map seoOut = ec.service.sync().name('org.moqui.impl.WikiServices.get#PublishedWikiPageText')
                .parameters([wikiSpaceId: wikiSpaceId, pagePath: pagePathPrefix + seoPagePath]).call()
        if (!seoOut?.pageText && pagePathPrefix)
            seoOut = ec.service.sync().name('org.moqui.impl.WikiServices.get#PublishedWikiPageText')
                    .parameters([wikiSpaceId: wikiSpaceId, pagePath: seoPagePath]).call()
        String seoText = seoOut?.pageText
        if (seoText) {
            def dMatch = (seoText =~ /(?i)description:\s*(.*?)\s*-->/)
            if (dMatch.find()) context.pageDescription = dMatch.group(1)
            def tMatch = (seoText =~ /(?i)title:\s*(.*?)\s*-->/)
            if (tMatch.find()) context.pageTitle = tMatch.group(1)
            if (!context.pageTitle) seoText.eachLine {
                if (!context.pageTitle && (it.startsWith('# ') || it.startsWith('## ')))
                    context.pageTitle = it.substring(it.indexOf(' ') + 1)
            }
            // no description front matter: use the first real sentence of the page
            if (!context.pageDescription) {
                String plain = seoText.replaceAll(/(?s)<#--.*?-->/, '').replaceAll(/(?s)<!--.*?-->/, '')
                        .replaceAll(/(?s)<#[^>]*>/, '').replaceAll(/\$\{[^}]*\}/, '')
                        .replaceAll(/(?s)<[^>]+>/, ' ').replaceAll(/[*`#\[\]]/, ' ')
                String para = plain.readLines().collect({ it.replaceAll(/\s+/, ' ').trim() })
                        .find({ it.length() > 40 })
                if (para) {
                    if (para.length() > 155) {
                        int cut = para.substring(0, 155).lastIndexOf(' ')
                        para = para.substring(0, cut > 0 ? cut : 155) + '...'
                    }
                    context.pageDescription = para
                }
            }
        }
    } catch (Exception e) { ec.logger.warn("Page SEO meta lookup failed: ${e.message}") }
    context.seoPageType = 'content'
    // breadcrumbs for the schema.org BreadcrumbList
    List crumbs = [[title: storeInfo.productStore.storeName, url: (urlPrefix ?: '') + '/']]
    String crumbPath = ''
    for (String segment in seoPagePath.split('/')) {
        crumbPath = crumbPath ? crumbPath + '/' + segment : segment
        Map crumbPage = ((List) (storeInfo.pages ?: [])).find({ it.path == crumbPath })
        crumbs.add([title: crumbPage?.title ?: segment,
                    url: (urlPrefix ?: '') + '/content/' + crumbPath])
    }
    context.seoBreadcrumbs = crumbs
}
// absolute urls for canonical/og/markdown; note requestUrl carries the query string,
// which must not end up in the canonical
String scheme = ec.web.request.getHeader('X-Forwarded-Proto') ?: ec.web.request.getScheme()
context.siteBaseUrl = scheme + '://' + ec.web.getHostName(true)
context.pageCanonicalUrl = context.siteBaseUrl + (seoPathInfo ?: '/')
// only the home and content pages have a markdown twin, see SeoServices get#PageMarkdown
if (seoLocalePath == '/' || seoLocalePath == '' || seoLocalePath.startsWith('/content/'))
    context.pageMarkdownUrl = context.siteBaseUrl + '/md' + (seoPathInfo == '' ? '/' : seoPathInfo)
// the same page in the other languages, for the <link rel="alternate"> tags and the
// language switcher; only the languages this site actually has pages for
List alternates = [[locale: 'x-default', url: context.siteBaseUrl + (seoLocalePath ?: '/')]]
for (String loc in (storeInfo.availableLocales ?: [])) {
    alternates.add([locale: loc,
        url: context.siteBaseUrl + '/' + loc + (seoLocalePath == '/' ? '' : seoLocalePath)])
}
context.pageAlternates = alternates
// each language in its own name, the way the app's language picker shows them
context.localeNames = [en: 'English', th: 'ไทย', zh: '中文', de: 'Deutsch',
                       fr: 'Français', nl: 'Nederlands']
